// ---- cenários de margem/preço do card de decisão (Nível 2) ----
// Reproduz a estrutura real: ST s/Valor e Sem Redução sempre usam a mesma alíquota (por isso saem
// idênticos); só Oficial (redução, exclusivo filiais 02/09) diverge. Simplificado pra ilustrar a
// navegação — não recria o motor fiscal completo com precisão de produção.
const FATOR_PRAZO_ATACADO = 1.0317;
const FATOR_PRAZO_VAREJO = 1.086435;

function calcularCenariosAtacado(p) {
  const custo = p.custoGerencial;
  const piscof = p.creditoPisCofins; // mesma taxa vale pra crédito de compra e incidência na venda
  const baseSemRed = custo / (1 - piscof - COMISSAO - p.icmsEfSemReducao - p.margemAlvo);
  const baseOficial = custo / (1 - piscof - COMISSAO - p.icmsEfSaida - p.margemAlvo);
  return [
    { id: "st_valor", nome: "ST s/Valor", real: p.modalidade === "ST_SUBSTITUTO", avista: baseSemRed, prazo: baseSemRed * FATOR_PRAZO_ATACADO },
    { id: "oficial", nome: "Oficial (c/ redução)", real: false, avista: baseOficial, prazo: baseOficial * FATOR_PRAZO_ATACADO },
    { id: "sem_red", nome: "Sem Redução", real: p.modalidade === "NORMAL", avista: baseSemRed, prazo: baseSemRed * FATOR_PRAZO_ATACADO },
  ];
}
function calcularCenariosVarejo(p) {
  const custo = p.custoGerencial;
  const piscof = p.creditoPisCofins;
  const baseSemRed = custo / (1 - piscof - COMISSAO - p.icmsEfSemReducao - p.margemAlvoVarejo);
  return [
    { id: "st_valor", nome: "ST s/Valor", real: p.modalidade === "ST_SUBSTITUTO", avista: baseSemRed, prazo: baseSemRed * FATOR_PRAZO_VAREJO },
    { id: "sem_red", nome: "Sem Redução", real: p.modalidade === "NORMAL", avista: baseSemRed, prazo: baseSemRed * FATOR_PRAZO_VAREJO },
  ];
}
function fmtR$(v) {
  return `R$ ${v.toFixed(2).replace(".", ",")}`;
}
function round2(v) {
  return Math.round(v * 100) / 100;
}
// MKP (markup) = multiplicador direto sobre o custo — PV = Custo × MKP (ex: MKP 1,35, 1,90).
// Convenção validada com a Cedep: é multiplicador puro, não percentual — diferente de margem.
function calcMKP(preco, custo) {
  return custo > 0 ? preco / custo : 0;
}
function calcMargemPct(preco, custo) {
  return preco > 0 ? ((preco - custo) / preco) * 100 : 0;
}
// Fórmula de margem validada contra 7 casos reais da V10 (diferença só de arredondamento):
// MC = 1 − PIS/COFINS(saída) − COMISSÃO − ICMS_EF(saída, do cenário) − custo/PV
// Pra ST_SUBSTITUTO e ST_RECOLHIDO, icmsEf é sempre 0 (ICMS-ST já resolvido na entrada/anterior).
const COMISSAO = 0.04;
function calcMargemReal(preco, custo, piscofSaida, icmsEf) {
  return preco > 0 ? 1 - piscofSaida - COMISSAO - icmsEf - custo / preco : 0;
}
function cenarioPorId(cenarios, id) {
  return cenarios.find((c) => c.id === id) || cenarios[0];
}
// Margem ATUAL (preço já praticado hoje) muda de fato conforme o cenário fiscal selecionado —
// são 3 valores reais diferentes na V10 (MARGEM_ST_s/VALOR, MARGEM_OFICIAL, MARGEM_SEM_RED),
// não um só. Varejo não tem "Oficial" (exclusivo filiais 02/09, só atacado) — cai pro Sem Redução.
function margemAtualPorCenario(p, cenarioSel, canal) {
  if (canal === "atacado") {
    if (cenarioSel === "st_valor") return p.margemAtacadoStValor;
    if (cenarioSel === "oficial") return p.margemAtacadoOficial;
    return p.margemAtacadoSemRed;
  }
  return cenarioSel === "st_valor" ? p.margemVarejoStValor : p.margemVarejoSemRed;
}
// Custo Gerencial TAMBÉM muda por cenário — confirmado com dados reais (CUSTO_TOT_s/VALOR vs
// CUSTO_TOT_GERENCIAL da V10 divergem pra produtos ST_SUBSTITUTO, porque o ICMS-ST entra no
// custo via MVA e a base de cálculo do MVA muda conforme o cenário). Padrão confirmado nos 8
// exemplos reais: ST_SUBSTITUTO → Sem Redução usa a mesma base do Oficial; NORMAL → Sem Redução
// usa a mesma base do ST s/Valor. custoGerencial já É o "Oficial" (inclui ajustes tipo Ingrax).
function custoPorCenario(p, cenarioSel) {
  if (cenarioSel === "st_valor") return p.custoStValor;
  if (cenarioSel === "oficial") return p.custoGerencial;
  return p.modalidade === "ST_SUBSTITUTO" ? p.custoGerencial : p.custoStValor;
}

// Badge de tributação — baseado na MODALIDADE real (3 valores possíveis na V10: ST_SUBSTITUTO,
// NORMAL, ST_RECOLHIDO), não em keyword-matching de texto livre. Monofásico é um atributo à
// parte (creditoPisCofins = 0), independente da modalidade.
function corTributacao(modalidade) {
  if (modalidade === "ST_SUBSTITUTO") return NAVY;
  if (modalidade === "ST_RECOLHIDO") return "#7C3AED";
  return "#6B7280";
}
function labelTributacaoCurta(modalidade) {
  if (modalidade === "ST_SUBSTITUTO") return "ST Substituto";
  if (modalidade === "ST_RECOLHIDO") return "ST Recolhido";
  return "Normal";
}

// Valor (NF, antes dos créditos) → Custo (depois de descontar crédito de ICMS + PIS/COFINS).
// Créditos variam por regime real (validado em 585 SKUs): lubrificante RE ST MVA 62,35% não
// tem crédito de ICMS (só PIS/COFINS 9,25%); monofásico não tem crédito de PIS/COFINS. Custo
// já validado noutras telas fica intacto — aqui só reconstruímos o Valor bruto correspondente.
function valorAntesDoCredito(custo, creditoICMS, creditoPisCofins) {
  return custo / ((1 - creditoICMS) * (1 - creditoPisCofins));
}

function aplicarFiltros(dados, f) {
  return dados.filter(
    (d) =>
      (f.fornecedor === "Todos" || d.fornecedor === f.fornecedor) &&
      (f.secao === "Todas" || d.secao === f.secao) &&
      (f.linha === "Todas" || d.linha === f.linha) &&
      (!f.status || f.status === "Todos" || d.status === f.status)
  );
}

function agregarPor(dados, campo) {
  const grupos = {};
  dados.forEach((d) => {
    const chave = d[campo];
    if (chave == null) return;
    if (!grupos[chave]) grupos[chave] = { nome: chave, faturamento: 0, peso: 0, litros: 0, quantidade: 0, somaCrescimento: 0, n: 0 };
    grupos[chave].faturamento += d.faturamento;
    grupos[chave].peso += d.peso;
    grupos[chave].litros += d.litros || 0;
    grupos[chave].quantidade += d.quantidade;
    grupos[chave].somaCrescimento += d.crescimentoYoY || 0;
    grupos[chave].n += 1;
  });
  return Object.values(grupos).map((g) => ({ ...g, crescimentoYoY: g.n ? g.somaCrescimento / g.n : 0 }));
}

