// "Hoje" fixo do protótipo (sexta-feira 28/08/2026), pra data ter base real
const HOJE = new Date(2026, 7, 28);
const NOMES_MES = ["Janeiro", "Fevereiro", "Março", "Abril", "Maio", "Junho", "Julho", "Agosto", "Setembro", "Outubro", "Novembro", "Dezembro"];

function formatarDataCurta(d) {
  return d.toLocaleDateString("pt-BR", { day: "2-digit", month: "2-digit" });
}
function inicioDaSemana(d) {
  const dia = d.getDay();
  const diff = dia === 0 ? -6 : 1 - dia; // semana começa na segunda
  const r = new Date(d);
  r.setDate(d.getDate() + diff);
  return r;
}
function rotuloPeriodo(granularidade, offset) {
  if (granularidade === "Dia") {
    if (offset === 0) return "Hoje";
    if (offset === -1) return "Ontem";
    const d = new Date(HOJE);
    d.setDate(HOJE.getDate() + offset);
    return formatarDataCurta(d);
  }
  if (granularidade === "Semana") {
    if (offset === 0) return "Essa semana";
    const ini = inicioDaSemana(HOJE);
    ini.setDate(ini.getDate() + offset * 7);
    const fim = new Date(ini);
    fim.setDate(ini.getDate() + 6);
    return `${formatarDataCurta(ini)} a ${formatarDataCurta(fim)}`;
  }
  if (granularidade === "Mês") {
    if (offset === 0) return "Esse mês";
    const d = new Date(HOJE.getFullYear(), HOJE.getMonth() + offset, 1);
    return `${NOMES_MES[d.getMonth()]}/${d.getFullYear()}`;
  }
  if (granularidade === "Ano") {
    if (offset === 0) return "Esse ano";
    return String(HOJE.getFullYear() + offset);
  }
  return "";
}

// Comparação com o ano anterior — quando o período selecionado é o CORRENTE (offset 0), o mês/
// semana/ano ainda não fechou, então a comparação usa só a fatia proporcional do ano passado até
// hoje (ex: agosto no dia 28 compara com 1-28/ago do ano passado, não o mês inteiro). Período já
// fechado (offset != 0) compara cheio contra cheio, sem precisar de corte.
function rotuloComparacaoAno(granularidade, offset) {
  const ehAtual = offset === 0;
  if (granularidade === "Dia") {
    const d = new Date(HOJE);
    d.setDate(HOJE.getDate() + offset);
    return `vs. ${formatarDataCurta(d)}/${d.getFullYear() - 1}`;
  }
  if (granularidade === "Semana") {
    if (ehAtual) return `vs. mesma semana do ano passado, até ${formatarDataCurta(HOJE)} (proporcional)`;
    return "vs. semana equivalente do ano passado (completa)";
  }
  if (granularidade === "Mês") {
    if (ehAtual) return `vs. ${NOMES_MES[HOJE.getMonth()]}/${HOJE.getFullYear() - 1} até dia ${HOJE.getDate()} (proporcional)`;
    const d = new Date(HOJE.getFullYear(), HOJE.getMonth() + offset, 1);
    return `vs. ${NOMES_MES[d.getMonth()]}/${d.getFullYear() - 1} (mês completo)`;
  }
  if (granularidade === "Ano") {
    if (ehAtual) return `vs. 01/01 a ${formatarDataCurta(HOJE)}/${HOJE.getFullYear() - 1} (proporcional)`;
    return `vs. ${HOJE.getFullYear() + offset - 1} (ano completo)`;
  }
  return "vs. período anterior";
}

// ---- conversão offset <-> valor de input nativo (calendário/mês/semana/ano) ----
function paraISOWeek(d) {
  const alvo = new Date(d);
  alvo.setDate(alvo.getDate() + 3); // quinta-feira da semana (padrão ISO)
  const primeiraQuinta = new Date(alvo.getFullYear(), 0, 4);
  const semana = 1 + Math.round((alvo - primeiraQuinta) / (7 * 86400000));
  return `${alvo.getFullYear()}-W${String(semana).padStart(2, "0")}`;
}
function deISOWeek(ano, semana) {
  const simples = new Date(ano, 0, 1 + (semana - 1) * 7);
  const diaSemana = simples.getDay();
  const inicio = new Date(simples);
  if (diaSemana <= 4) inicio.setDate(simples.getDate() - diaSemana + 1);
  else inicio.setDate(simples.getDate() + 8 - diaSemana);
  return inicio;
}
function offsetParaValorInput(granularidade, offset) {
  if (granularidade === "Dia") {
    const d = new Date(HOJE);
    d.setDate(HOJE.getDate() + offset);
    return d.toISOString().slice(0, 10);
  }
  if (granularidade === "Semana") {
    const ini = inicioDaSemana(HOJE);
    ini.setDate(ini.getDate() + offset * 7);
    return paraISOWeek(ini);
  }
  if (granularidade === "Mês") {
    const d = new Date(HOJE.getFullYear(), HOJE.getMonth() + offset, 1);
    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}`;
  }
  if (granularidade === "Ano") return String(HOJE.getFullYear() + offset);
  return "";
}
function valorInputParaOffset(granularidade, valor) {
  if (!valor) return 0;
  if (granularidade === "Dia") {
    const d = new Date(valor + "T00:00:00");
    return Math.round((d - HOJE) / 86400000);
  }
  if (granularidade === "Semana") {
    const [anoStr, semStr] = valor.split("-W");
    const d = deISOWeek(Number(anoStr), Number(semStr));
    const iniHoje = inicioDaSemana(HOJE);
    return Math.round((d - iniHoje) / (7 * 86400000));
  }
  if (granularidade === "Mês") {
    const [anoStr, mesStr] = valor.split("-");
    return (Number(anoStr) - HOJE.getFullYear()) * 12 + (Number(mesStr) - 1 - HOJE.getMonth());
  }
  if (granularidade === "Ano") return Number(valor) - HOJE.getFullYear();
  return 0;
}
const TIPO_INPUT = { Dia: "date", Semana: "week", Mês: "month", Ano: "number" };

// Seletor de período específico — sempre nasce no atual (offset 0), navega pra trás/frente
// com as setas, ou toca no rótulo pra abrir o calendário nativo (ou digitar direto, no caso
// de Ano). Reseta pra 0 sempre que a granularidade (Dia/Semana/Mês/Ano) muda.
function SeletorPeriodo({ granularidade, offset, setOffset }) {
  const [editando, setEditando] = useState(false);
  const tipoInput = TIPO_INPUT[granularidade];

  return (
    <div className="flex items-center justify-between mt-2 bg-gray-50 rounded-lg px-1 py-1">
      <button onClick={() => setOffset(offset - 1)} className="p-1.5 rounded-md active:bg-gray-200 shrink-0">
        <ChevronLeft size={14} className="text-gray-500" />
      </button>

      {editando ? (
        <input
          type={tipoInput}
          autoFocus
          defaultValue={offsetParaValorInput(granularidade, offset)}
          max={tipoInput === "number" ? String(HOJE.getFullYear()) : offsetParaValorInput(granularidade, 0)}
          onChange={(e) => { if (e.target.value) setOffset(valorInputParaOffset(granularidade, e.target.value)); }}
          onBlur={() => setEditando(false)}
          className="text-[12px] font-medium text-gray-700 text-center border border-gray-300 rounded-md px-2 py-1 bg-white"
        />
      ) : (
        <button onClick={() => setEditando(true)} className="text-[12px] font-medium text-gray-700 flex items-center gap-1 px-2">
          <Calendar size={12} className="text-gray-400" />
          {rotuloPeriodo(granularidade, offset)}
        </button>
      )}

      <button onClick={() => setOffset(Math.min(0, offset + 1))} disabled={offset >= 0} className="p-1.5 rounded-md active:bg-gray-200 shrink-0">
        <ChevronRight size={14} className={offset >= 0 ? "text-gray-300" : "text-gray-500"} />
      </button>
    </div>
  );
}

