// ---------- Tela 3: Entradas recentes ----------
function isMasterFornecedor(fornecedor) {
  return ["YPF", "INGRAX", "PETRONAS", "KOUBE", "VALVOLINE"].includes(fornecedor);
}

// Download via Blob + link manual — mais robusto que XLSX.writeFile em ambientes com iframe
// restrito (o preview de artifact costuma bloquear o mecanismo interno da biblioteca).
function baixarArquivo(wb, nomeArquivo) {
  try {
    const wbout = XLSX.write(wb, { bookType: "xlsx", type: "array" });
    const blob = new Blob([wbout], { type: "application/octet-stream" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = nomeArquivo;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    setTimeout(() => URL.revokeObjectURL(url), 2000);
  } catch (e) {
    alert("Não foi possível baixar automaticamente aqui no preview — provavelmente o ambiente está bloqueando download. Erro: " + e.message);
  }
}

// ---- exportações do pedido salvo ----
// Formato Winthor rotina 220 (confirmado na documentação oficial TOTVS):
// só 3 colunas — Código do produto | Preço Unitário | Quantidade Pedida — sem cabeçalho,
// só aceita .XLS/.XLSX (não aceita .csv). Filial/Fornecedor/Comprador são digitados
// na tela do Winthor na hora de importar, não vão na planilha.
function exportarWinthor(pedidoSalvo) {
  const linhas = pedidoSalvo.itens.map((it) => [it.codigo, Number(it.precoUnitario.toFixed(2)), it.unidades]);
  const ws = XLSX.utils.aoa_to_sheet(linhas);
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, "Pedido");
  baixarArquivo(wb, `winthor_pedido_${pedidoSalvo.fornecedor}_${pedidoSalvo.id}.xlsx`);
}

// Orçamento em Excel — versão rica, pra negociar com o fornecedor (não é o formato Winthor,
// não vai pro Winthor diretamente — serve só de comunicação/negociação). Inclui o código do
// fornecedor (cód. de fábrica) porque é assim que o fornecedor de fato identifica o produto —
// o código da CEDEP sozinho não diz nada pra eles.
function exportarOrcamentoExcel(pedidoSalvo) {
  const cabecalho = ["Cód. CEDEP", "Cód. Fornecedor", "Produto", "Embalagem", "Quantidade", "Unidade", "Preço Unit.", "Total"];
  const linhas = pedidoSalvo.itens.map((it) => [
    it.codigo, it.codFab || "", it.nome, it.embalagem, it.quantidadeDigitada, it.isMaster ? "caixa" : "unidade", it.precoUnitario, it.valorItem,
  ]);
  const ws = XLSX.utils.aoa_to_sheet([cabecalho, ...linhas]);
  ws["!cols"] = [{ wch: 10 }, { wch: 14 }, { wch: 40 }, { wch: 14 }, { wch: 12 }, { wch: 10 }, { wch: 12 }, { wch: 12 }];
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, "Orcamento");
  baixarArquivo(wb, `orcamento_${pedidoSalvo.fornecedor}_${pedidoSalvo.id}.xlsx`);
}

// Orçamento em PDF — via overlay dentro do próprio app + window.print(), sem abrir popup
// (window.open costuma ser bloqueado no preview de artifact; impressão da própria janela não é)
